class Solution:
    def solveNQueens(self, n: int) -&gt; List[List[str]]:
        res, cols = [], []
        used_c, used_d, used_a = set(), set(), set()

        def dfs(r):
            if r == n:
                res.append(["." * c + "Q" + "." * (n - c - 1) for c in cols])
                return
            for c in range(n):
                if c in used_c or r - c in used_d or r + c in used_a:
                    continue
                used_c.add(c); used_d.add(r - c); used_a.add(r + c)
                cols.append(c)
                dfs(r + 1)
                cols.pop()
                used_c.remove(c); used_d.remove(r - c); used_a.remove(r + c)

        dfs(0)
        return res

